//! The inputs the writer applies to the queue, and what each one answers.
//!
//! Every input carries `now` (the server's clock when the HTTP request or
//! the timer fired): the rules never read a clock (OQ-10).  Everything else
//! that comes from outside the writer is in the input too: the fresh lease
//! token (random, generated by the HTTP layer), the engine-gate verdict
//! (computed from the policy file and the engines directory, Q-9), the
//! certificate verdict of a proof (computed by a preparer).
//!
//! Authentication (Q-2.1, Q-2.30) and form parsing (Q-2.2, Q-2.32, Q-2.35..
//! Q-2.37, Q-2.47) happen before an input exists: `account` is the
//! authenticated user, numbers are already sanitised (see `protocol` for the
//! parsers the HTTP layer uses).

use crate::config::QueueConfig;
use crate::consts::Ms;
use crate::model::{Pref, Serving, Source};
use serde::{Deserialize, Serialize};

/// Capacity telemetry carried by lease, heartbeat and solve calls (Q-2.3).
#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
pub struct Telemetry {
    /// `reported_threads` (clamped to 0..=1024).
    #[serde(default)]
    pub threads: u32,
    #[serde(default)]
    pub hash_mb: u64,
    #[serde(default)]
    pub os: String,
    /// `reported_worker_build`: only a value in 1..=2^31-1, else None.
    #[serde(default)]
    pub worker_build: Option<i64>,
}

#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
pub struct LeaseReq {
    pub now: Ms,
    pub account: String,
    /// POST `machine` (default: the account), first 64 chars: the slot.
    pub machine: String,
    #[serde(default)]
    pub telemetry: Telemetry,
    /// `int(POST worker_build or 0)` (0 on error), for the capability test.
    #[serde(default)]
    pub build: i64,
    /// POST `lease_session`, first 64 chars.
    #[serde(default)]
    pub session: String,
    /// The fresh token this lease hands out if it hands one out.
    pub token: String,
    #[serde(default)]
    pub max_budget: Option<u64>,
    /// POST `tb == '1'`.
    #[serde(default)]
    pub tb: bool,
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct LeaseGrant {
    pub id: u64,
    pub pos: u64,
    pub budget: u64,
    pub multipv: u32,
    pub token: String,
    pub source: Source,
    pub requested_by: String,
    pub route: String,
    /// The same assignment answered again (Q-2.10).
    pub replayed: bool,
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(tag = "result", rename_all = "snake_case")]
pub enum LeaseOut {
    /// `{"tasks": [task]}`.
    Task { grant: LeaseGrant },
    /// `{"tasks": []}`, the slot holds this live lease (Q-2.12).
    Busy { held: u64 },
    /// `{"tasks": []}`: machine cap (Q-2.13) or nothing to serve.
    Empty,
    /// D8: a build older than `LEASE_TOKEN_BUILD` gets no lease at all.
    UpgradeRequired,
}

#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
pub struct HeartbeatReq {
    pub now: Ms,
    pub account: String,
    pub machine: String,
    #[serde(default)]
    pub telemetry: Telemetry,
    /// None = idle heartbeat.
    #[serde(default)]
    pub task: Option<u64>,
    #[serde(default)]
    pub token: String,
    /// Clamped to 0..=1e12.
    #[serde(default)]
    pub nps: u64,
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(tag = "result", rename_all = "snake_case")]
pub enum HeartbeatOut {
    Ok { machine: String, current: Option<u64> },
    StaleLease,
}

#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
pub struct SubmitReq {
    pub now: Ms,
    pub account: String,
    /// POST `machine`, default '' (not the account, Q-2.38).
    #[serde(default)]
    pub machine: String,
    pub task: u64,
    #[serde(default)]
    pub token: String,
    /// Sanitised (Q-2.36).
    #[serde(default)]
    pub nodes: u64,
    #[serde(default)]
    pub elapsed: f64,
    /// Cleaned by `_sha_field` (Q-2.37).
    #[serde(default)]
    pub engine_sha: String,
    #[serde(default)]
    pub net_sha: String,
    #[serde(default)]
    pub tb_wdl: Option<i64>,
    #[serde(default)]
    pub tb_dtz: Option<i64>,
    /// `bool(POST searchmoves.split())` (Q-2.43).
    #[serde(default)]
    pub restricted: bool,
    /// `engine_policy.rejects(engine_sha, tablebase)` evaluated by the HTTP
    /// layer at receipt (Q-9.4); applied only after the ownership checks.
    #[serde(default)]
    pub gate_rejects: bool,
    /// The validated `lines` JSON exactly as received (Q-2.35).
    #[serde(default)]
    pub lines: String,
}

/// What an accepted submit hands to the landing pipeline (v1 `IngestJob`
/// payload plus the task context `apply_job` reads, Q-2.43, Q-3.9).
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct Claim {
    pub task: u64,
    pub pos: u64,
    pub budget: u64,
    pub multipv: u32,
    pub source: Source,
    pub arm: String,
    pub requested_by: String,
    pub also: Vec<String>,
    pub then_verify: bool,
    pub lines: String,
    /// Clamped to twice the authoritative budget (Q-2.42).
    pub nodes: u64,
    pub elapsed: f64,
    pub machine: String,
    pub username: String,
    pub tb_wdl: Option<i64>,
    pub tb_dtz: Option<i64>,
    pub restricted: bool,
    pub engine_sha: String,
    pub net_sha: String,
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(tag = "result", rename_all = "snake_case")]
pub enum SubmitOut {
    Accepted {
        claim: Box<Claim>,
    },
    /// `200 {"ok": true, "dup": true}`.
    Dup,
    /// `400 {"error": "malformed: unknown task"}`.
    UnknownTask,
    /// `400 {"error": "not-leased"}`.
    NotLeased,
    /// `409 {"error": "not-your-lease"}`.
    NotYourLease,
    /// `409 {"error": "stale-lease"}`.
    StaleLease,
    /// `403 {"error": "engine-not-accepted"}` (Q-2.40).
    EngineRefused,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum LeaseKind {
    Analysis,
    Solve,
}

#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
pub struct ReleaseEntry {
    pub kind: LeaseKind,
    pub task: u64,
    pub token: String,
    /// Owner slot (default: the caller's machine), first 64 chars.
    pub owner: String,
}

#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
pub struct ReleaseReq {
    pub now: Ms,
    pub account: String,
    pub machine: String,
    pub entries: Vec<ReleaseEntry>,
}

#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
pub struct SolveAcquireReq {
    pub now: Ms,
    pub account: String,
    pub machine: String,
    #[serde(default)]
    pub telemetry: Telemetry,
    #[serde(default)]
    pub session: String,
    pub token: String,
    #[serde(default)]
    pub max_budget: Option<u64>,
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct SolveGrant {
    pub id: u64,
    pub pos: u64,
    pub goal: String,
    pub stage: String,
    pub budget: u64,
    pub token: String,
    pub replayed: bool,
}

#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
pub struct SolveHeartbeatReq {
    pub now: Ms,
    pub account: String,
    pub machine: String,
    #[serde(default)]
    pub telemetry: Telemetry,
    pub task: u64,
    #[serde(default)]
    pub token: String,
}

/// The server's verdict on a submitted certificate, computed by a preparer
/// before the input reaches the writer (Q-2.61: verification runs outside
/// the transaction).
#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
pub struct SolveVerdict {
    /// `verified` (PROVED with a certificate that verifies).
    pub verified: bool,
    /// The rejection reason when PROVED does not verify.
    #[serde(default)]
    pub reason: String,
}

#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
pub struct SolveSubmitReq {
    pub now: Ms,
    pub account: String,
    #[serde(default)]
    pub machine: String,
    pub task: u64,
    #[serde(default)]
    pub token: String,
    /// `PROVED`, `DISPROVED` or `UNKNOWN` (validated, Q-2.59).
    pub outcome: String,
    #[serde(default)]
    pub verdict: SolveVerdict,
    #[serde(default)]
    pub nodes: u64,
    #[serde(default)]
    pub elapsed: f64,
    #[serde(default)]
    pub solver_build: String,
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(tag = "result", rename_all = "snake_case")]
pub enum SolveSubmitOut {
    Dup,
    UnknownTask,
    NotLeased,
    NotYourLease,
    StaleLease,
    /// PROVED without a verifying certificate: FAILED, `SOLVE_REJECTED`.
    Rejected {
        pos: u64,
        reason: String,
    },
    /// COMPLETED; the rules apply the closure effects (SOL-2).
    Completed {
        pos: u64,
        goal: String,
        outcome: String,
        verified: bool,
    },
}

/// A person's request (`views._queue_request` + `ingest.request_analysis`).
#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
pub struct RequestReq {
    pub now: Ms,
    /// '' = anonymous.
    #[serde(default)]
    pub account: String,
    pub pos: u64,
    /// Client address for the hour dedup (Q-6.25); never leaves the writer
    /// state except in the log.
    #[serde(default)]
    pub ip: String,
    /// Already validated route (or '').
    #[serde(default)]
    pub route: String,
    /// The validated chosen rung (Q-5.2), if any.
    #[serde(default)]
    pub budget_floor: Option<u64>,
    #[serde(default)]
    pub only_if_missing: bool,
    #[serde(default)]
    pub one_search: bool,
    #[serde(default)]
    pub only_unexplored: bool,
    #[serde(default)]
    pub background: bool,
    /// POST `then_verify == '1'` (Q-6.27).
    #[serde(default)]
    pub then_verify: bool,
    /// Q-6.26 `with_place`: the HTTP layer adds `ahead` after the commit
    /// (`QueueState::user_queue_ahead` on a read copy); logged for the audit.
    #[serde(default)]
    pub with_place: bool,
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct RequestOut {
    /// Wire status (`queued`, `already-queued`, ...).
    pub status: String,
    /// Extra keys merged into the JSON answer (`adopted`, `completed_budget`,
    /// `ahead`, `then_verify`, `retry_after`...).
    pub detail: serde_json::Map<String, serde_json::Value>,
}

/// A task proposed by the selector or an arm (minted by the writer if the
/// slot is free, PRI-4.11).
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct MintTask {
    pub pos: u64,
    pub budget: u64,
    pub multipv: u32,
    pub source: Source,
    #[serde(default)]
    pub arm: String,
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(tag = "op", rename_all = "snake_case")]
pub enum Input {
    Lease(LeaseReq),
    Heartbeat(HeartbeatReq),
    Submit(SubmitReq),
    Release(ReleaseReq),
    SolveAcquire(SolveAcquireReq),
    SolveHeartbeat(SolveHeartbeatReq),
    SolveSubmit(SolveSubmitReq),
    Request(RequestReq),
    /// `withdraw` door (Q-6.38): the author takes a PENDING request back.
    Withdraw {
        now: Ms,
        account: String,
        task: u64,
    },
    /// Undo a withdrawal (Q-6.21).
    Undo {
        now: Ms,
        account: String,
        task: u64,
    },
    /// Clear own queue (Q-6.20).
    ClearQueue {
        now: Ms,
        account: String,
    },
    /// Move to front (Q-6.37).
    Bump {
        now: Ms,
        account: String,
        task: u64,
    },
    /// Preferences of an account (Q-1.18, Q-6.41).
    SetPref {
        now: Ms,
        account: String,
        pref: Pref,
    },
    /// Per-machine override (Q-1.19).
    SetServing {
        now: Ms,
        account: String,
        machine: String,
        serving: Serving,
    },
    /// A position closed (CAS-7: absorb its PENDING tasks).
    PositionClosed {
        now: Ms,
        pos: u64,
    },
    /// A search landed (EXP-5.2 / Q-3.13: absorb the requests it covers).
    Landed {
        now: Ms,
        pos: u64,
        task: Option<u64>,
        arbiter: u64,
    },
    /// Tombstone revivals (PRI-1.7 a-d).
    Revive {
        now: Ms,
        positions: Vec<u64>,
    },
    /// Selector proposals applied as they are (PRI-4.2, PRI-4.4).
    Mint {
        now: Ms,
        plan: crate::selector::MintPlan,
    },
    /// Pool top-up (PRI-4.3) through the writer's `Refill`; `target`
    /// defaults to `config.pool_target`.
    Pool {
        now: Ms,
        #[serde(default)]
        target: Option<usize>,
    },
    /// The enqueue half of a background arm (Q-8.7, Q-8.9, Q-8.12, Q-8.14).
    Arm {
        now: Ms,
        step: crate::arms::ArmStep,
    },
    /// The quality arm's purchases made by the backed ascent (Q-8.15,
    /// BKD-11, `quality.rs`).  Applying it changes nothing: the rules made
    /// the purchases and the record's deltas carry them.
    Purchases {
        now: Ms,
    },
    /// The value cascade of a landing (PRI-4.9).
    Cascade {
        now: Ms,
        pos: u64,
        open_before: bool,
    },
    /// The unexplored-moves button and the AUTO callers of
    /// `enqueue_unexplored_children` (Q-8.18..Q-8.21).
    BulkChildren {
        now: Ms,
        account: String,
        pos: u64,
        #[serde(default)]
        route: String,
        source: Source,
        #[serde(default)]
        children: Option<Vec<u64>>,
    },
    /// Periodic step: solve-lease recycle (SOL-5.4), retention.
    Tick {
        now: Ms,
    },
    SetConfig {
        now: Ms,
        config: Box<QueueConfig>,
    },
}

impl Input {
    pub fn now(&self) -> Ms {
        match self {
            Input::Lease(r) => r.now,
            Input::Heartbeat(r) => r.now,
            Input::Submit(r) => r.now,
            Input::Release(r) => r.now,
            Input::SolveAcquire(r) => r.now,
            Input::SolveHeartbeat(r) => r.now,
            Input::SolveSubmit(r) => r.now,
            Input::Request(r) => r.now,
            Input::Withdraw { now, .. }
            | Input::Undo { now, .. }
            | Input::ClearQueue { now, .. }
            | Input::Bump { now, .. }
            | Input::SetPref { now, .. }
            | Input::SetServing { now, .. }
            | Input::PositionClosed { now, .. }
            | Input::Landed { now, .. }
            | Input::Revive { now, .. }
            | Input::Mint { now, .. }
            | Input::Pool { now, .. }
            | Input::Arm { now, .. }
            | Input::Cascade { now, .. }
            | Input::Purchases { now }
            | Input::BulkChildren { now, .. }
            | Input::Tick { now }
            | Input::SetConfig { now, .. } => *now,
        }
    }
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(tag = "out", rename_all = "snake_case")]
pub enum Output {
    Lease(LeaseOut),
    Heartbeat(HeartbeatOut),
    Submit(SubmitOut),
    Release {
        released: usize,
    },
    SolveAcquire {
        task: Option<SolveGrant>,
    },
    SolveHeartbeat {
        ok: bool,
    },
    SolveSubmit(SolveSubmitOut),
    Request(RequestOut),
    /// `withdrawn` / `handed-over` / `refused`...
    Status {
        status: String,
    },
    Cleared {
        withdrawn: usize,
        handed: usize,
    },
    Absorbed {
        count: usize,
    },
    Minted {
        created: usize,
        pending: Vec<u64>,
    },
    /// Rows made by an arm, a cascade or the bulk button.
    Made {
        count: usize,
    },
    Tick {
        recycled_solves: usize,
        pruned: usize,
    },
    Ok,
}
